/**
 * Bearer-token + Origin validation for the dev-browser HTTP/WS surfaces
 * (:9224 launch server and extension relay — Phase 3 M1 §5.3).
 *
 * The token is generated by the spawning side (daemon / task bootstrap) and
 * arrives via `ACCOMPLISH_DEV_BROWSER_TOKEN` in the sidecar's spawn env. All
 * consumers (dev-browser-mcp tool child) receive the same value via the
 * generated OpenCode config env.
 *
 * Timing-safe comparison mirrors apps/host/src/auth.ts and
 * agent-core utils/service-token.ts.
 */

import { createHash, randomBytes, timingSafeEqual } from 'node:crypto';

const TOKEN_BYTES = 32;

export function generateBrowserToken(): string {
  return randomBytes(TOKEN_BYTES).toString('base64url');
}

export function resolveBrowserToken(optionsToken: string | undefined): string {
  const fromEnv = process.env.ACCOMPLISH_DEV_BROWSER_TOKEN;
  if (fromEnv && fromEnv.trim().length > 0) {
    return fromEnv.trim();
  }
  if (optionsToken && optionsToken.trim().length > 0) {
    return optionsToken.trim();
  }
  // Self-protecting default — a manually-started sidecar still has a token;
  // clients then need the same value in their env, which surfaces a clear 401
  // instead of silently running an unauthenticated local service.
  return generateBrowserToken();
}

export function extractBearerToken(header: string | undefined): string | null {
  if (!header) {
    return null;
  }
  const [scheme, value] = header.split(' ', 2);
  if (scheme?.toLowerCase() !== 'bearer' || !value) {
    return null;
  }
  return value.trim();
}

/** Constant-time token equality (hashed so lengths never leak). Empty never equals. */
export function timingSafeTokenEquals(a: string, b: string): boolean {
  if (a.length === 0 || b.length === 0) {
    return false;
  }
  const ha = createHash('sha256').update(a).digest();
  const hb = createHash('sha256').update(b).digest();
  return timingSafeEqual(ha, hb);
}

/**
 * Verify any of the accepted WS/HTTP credential headers against the expected
 * token: Authorization Bearer, X-CDP-Secret, or x-accomplish-dev-browser-token.
 * Returns null when no header carried a credential; true/false when one did.
 */
export function verifyAnyCredentialHeader(
  headers: Record<string, string | string[] | undefined>,
  expectedToken: string,
): boolean | null {
  const candidates: Array<string | undefined> = [];
  const auth = headers['authorization'];
  if (typeof auth === 'string') {
    candidates.push(extractBearerToken(auth) ?? undefined);
  }
  const secret = headers['x-cdp-secret'];
  if (typeof secret === 'string') {
    candidates.push(secret.trim());
  }
  const dedicated = headers['x-accomplish-dev-browser-token'];
  if (typeof dedicated === 'string') {
    candidates.push(dedicated.trim());
  }

  if (candidates.length === 0) {
    return null;
  }
  return candidates.some(
    (value) => value !== undefined && timingSafeTokenEquals(value, expectedToken),
  );
}
